#!/usr/bin/env bash
set -Eeuo pipefail
ROOT=$(mktemp -d); trap 'rm -rf "$ROOT"' EXIT
repo="$ROOT/repo"; remote="$ROOT/remote.git"; mkdir -p "$repo"; git init -q --bare "$remote"; git clone -q "$remote" "$repo/main"; git -C "$repo/main" config user.email test@example.invalid; git -C "$repo/main" config user.name test; printf seed > "$repo/main/file"; git -C "$repo/main" add file; git -C "$repo/main" commit -qm seed; git -C "$repo/main" branch -M main; git -C "$repo/main" push -qu origin main; git -C "$repo/main" worktree add -qb clean-branch "$repo/clean"; git -C "$repo/main" worktree add -qb dirty-branch "$repo/dirty"; git -C "$repo/clean" push -qu -u origin clean-branch; printf 'path=%s\nlifecycle_state=READY_FOR_CLEANUP\n' "$repo/clean" > "$repo/clean/.thoidai-lifecycle"; git -C "$repo/dirty" push -qu -u origin dirty-branch; printf dirty >> "$repo/dirty/file"; printf untracked > "$repo/dirty/untracked"
export THOIDAI_SOURCE_REPO="$repo/main" THOIDAI_WORKTREE_ROOT="$repo" THOIDAI_LOCK_FILE="$ROOT/lock" THOIDAI_TEST_MODE=1 THOIDAI_OWNER_APPROVED_CLEANUP=1 THOIDAI_PGREP_BIN=/bin/false THOIDAI_LSOF_BIN=/bin/false
out=$(scripts/production/worktree-cleanup.sh); echo "$out" | grep -q $'DELETE\t.*clean\tclean-upstream-reachable'; echo "$out" | grep -q $'REVIEW\t.*dirty\tmissing-lifecycle-metadata'; scripts/production/worktree-cleanup.sh --apply >/dev/null; [ ! -e "$repo/clean" ]; [ -e "$repo/dirty" ]; echo PASS worktree-cleanup